from datetime import date, timedelta


class LeaveTracker:
    def __init__(
        self, days_per_year: int = 26, holidays: list[date] | None = None
    ) -> None:
        self._days_per_year = days_per_year
        self._holidays = set(holidays or [])
        self._used: dict[tuple[str, int], int] = {}
        self._employees: set[str] = set()
        self._requests: dict[str, list[tuple[date, date]]] = {}

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        if end < start:
            raise ValueError("End date cannot be before start date")
        if (start - today).days < 3:
            raise ValueError("Leave must be requested at least 3 days in advance")

        days_by_year: dict[int, int] = {}
        current = start
        while True:
            if current.weekday() < 5 and current not in self._holidays:
                days_by_year[current.year] = days_by_year.get(current.year, 0) + 1
            if current == end:
                break
            current += timedelta(days=1)

        for year, days in days_by_year.items():
            if days > self.remaining(employee, year):
                raise ValueError(f"Insufficient leave remaining for {year}")

        for year, days in days_by_year.items():
            key = (employee, year)
            self._used[key] = self._used.get(key, 0) + days

        self._employees.add(employee)
        self._requests.setdefault(employee, []).append((start, end))
        return sum(days_by_year.values())

    def remaining(self, employee: str, year: int) -> int:
        return self._days_per_year - self._used.get((employee, year), 0)

    def employees(self) -> list[str]:
        return sorted(self._employees)

    def requests_of(self, employee: str) -> list[tuple[date, date]]:
        """Return the employee's successful requests in submission order."""
        return list(self._requests.get(employee, []))
```

